create or replace TABLE KFL_PRODUCTION.DBP_ETL.LAGERBESTAND_ERP_PER_STEP03 cluster by (
     MANDANT_ID,
     DAT,
     WUP_ID
)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant im DWH. Zuteilung zum Land.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel-ID einschließlich der Generationen-ID (9-stellig); Output: 7-stellige L&S-ID + Counter = 8-stellige Artikel-ID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel -> Counter +1.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'WUP: Warenumschlagsplatz. ID des Lagers / Verteilzentrum (VZ)',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'NB: Nebenbetrieb. DWH-Kennzeichnung, um wup_ids unterscheiden zu können. Bspw.: 0 = Markt; -111 = Lager / VZ',
	LAGERORT_ID VARCHAR(4) NOT NULL COMMENT 'ID des Ortes im Lager, an dem der Artikel liegt. Die IDs unterscheiden sich zwischen den Ländern.',
	DAT DATE NOT NULL COMMENT 'Datum / Tag für den die Bestände und Kennzahlen gelten.',
	GP_ID NUMBER(38,0) COMMENT 'ID des Lieferanten, der für diesen Tag gemäß der Lieferantenzuordnung (dbp_data.art_gp_nm_zu_per) für diesen Artikel zugeordnet ist.',
	POSTEN_ID VARCHAR(2) COMMENT 'ID des Posten. Posten sind Artikel, die vom Markt in der Regel nicht nachbestellt werden können. Für einen Tag kann ein Artikel immer nur ein Posten oder Sortimentsartikel sein.',
	WRG_ID VARCHAR(3) NOT NULL COMMENT 'ID der Landeswährung des Landes aus der Mandant - Tabelle.',
	SPERR_ID VARCHAR(1) COMMENT 'Inventursperrkennzeichen: Gibt an, ob der Bestand für eine Inventur gesperrt ist (SAP-Quelle: MARD.SPERR).',
	GJMO_BUCH NUMBER(38,0) COMMENT 'Monat im Geschäftsjahr, in dem der Tagesbestand gebucht wurde (SAP-Quelle: MARD.LFMON).',
	LAGERORT_LOESCH_FG VARCHAR(1) COMMENT 'Gibt an, ober der Artikel aus dem Lagerort ausgetragen wird (SAP-Quelle: MARD.LVROM).',
	PFLEGE_STATUS VARCHAR(20) COMMENT 'Pflegestatus (SAP-Quelle: MARD.PSTAT).',
	MENGE_LGBEST_ERP_FREI_BME NUMBER(38,3) COMMENT 'Frei verwendbarer Bestand (kann an die Märkte geliefert werden) (SAP-Quelle: MARD.LABST).',
	MENGE_LGBEST_ERP_UMLAG_BME NUMBER(38,3) COMMENT 'Umlagerungsbestand: Bestand, der den Lagerort wechselt (SAP-Quelle: MARD.UMLMD).',
	MENGE_LGBEST_ERP_QUAL_BME NUMBER(38,3) COMMENT 'Qualitätsprüfbestand - Bestand, der für eine Qualitätsprüfung zurückgehalten wird (SAP-Quelle: MARD.INSME).',
	MENGE_LGBEST_ERP_NF_CHARGE_BME NUMBER(38,3) COMMENT 'Bestand, der nicht freien Chargen (SAP-Quelle: MARD.EINME).',
	MENGE_LGBEST_ERP_GESP_BME NUMBER(38,3) COMMENT 'Gesperrter Bestand, der nicht an den Markt geliefert werden darf (SAP-Quelle: MARD.SPEME).',
	MENGE_LGBEST_ERP_RET_GESP_BME NUMBER(38,3) COMMENT 'Retourensperrbestand: Bestand, der bereits für Retoure geplant ist (SAP-Quelle: MARD.RETME).',
	MENGE_LGBEST_ERP_GESAMT_BME NUMBER(38,3) COMMENT 'Summe aller Bestandstypen (Frei, Umlagerung, Qualitätsprüfung, Nicht freie Chargen, Gesperrt, Retoure).',
	MENGE_LGBEST_ERP_KOLLI NUMBER(38,3) COMMENT 'Umrechnung der gesamten Bestandsmenge von BME (Basismengeneinheit) in Kolli.',
	MENGE_LGBEST_ERP_PALETTE NUMBER(38,3) COMMENT 'Umrechnung der gesamten Bestandsmenge von BME (Basismengeneinheit) in Paletten.',
	VK_NETTO NUMBER(38,4) COMMENT 'Regulärer Verkaufspreis in Landeswährung (SAP-Quelle: ZVKP.KBETR).',
	VK_NETTO_KONZ NUMBER(38,4) COMMENT 'Regulärer Verkaufspreis in Konzernwährung (SAP-Quelle: ZVKP.KBETR).',
	BETRAG_VK_NETTO_LGBEST_ERP_FREI NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem regulären VK netto in Landeswährung: Freier Bestand * VK netto.',
	BETRAG_VK_NETTO_LGBEST_ERP_FREI_KONZ NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem regulären VK netto in Konzernwährung: Freier Bestand * VK netto_konz.',
	BETRAG_VK_NETTO_LGBEST_ERP_QUAL NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem regulären VK netto in Landeswährung: Qualitätsprüfbestand * VK netto.',
	BETRAG_VK_NETTO_LGBEST_ERP_QUAL_KONZ NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem regulären VK netto in Konzernwährung: Qualitätsprüfbestand * VK netto_konz.',
	BETRAG_VK_NETTO_LGBEST_ERP_GESAMT NUMBER(38,4) COMMENT 'Bewerteter gesamter Bestand mit dem regulären VK netto in Landeswährung: Gesamter Bestand * VK netto.',
	BETRAG_VK_NETTO_LGBEST_ERP_GESAMT_KONZ NUMBER(38,4) COMMENT 'Bewerteter gesamter Bestand mit dem regulären VK netto in Konzernwährung: Gesamter Bestand * VK netto_konz.',
	EK_NETTO NUMBER(38,4) COMMENT 'Rechnungs-Einkaufspreis in Landeswährung.',
	EK_NETTO_KONZ NUMBER(38,4) COMMENT 'Rechnungs-Einkaufspreis in Konzernwährung.',
	BETRAG_EK_NETTO_LGBEST_ERP_FREI NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem regulären EK netto (Rechnungs-Einkaufspreis) in Landeswährung: Freier Bestand * EK netto.',
	BETRAG_EK_NETTO_LGBEST_ERP_FREI_KONZ NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem regulären EK netto (Rechnungs-Einkaufspreis) in Konzernwährung: Freier Bestand * EK netto_konz.',
	BETRAG_EK_NETTO_LGBEST_ERP_QUAL NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem regulären EK netto (Rechnungs-Einkaufspreis) in Landeswährung: Qualitätsprüfbestand * EK netto.',
	BETRAG_EK_NETTO_LGBEST_ERP_QUAL_KONZ NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem regulären EK netto (Rechnungs-Einkaufspreis) in Konzernwährung: Qualitätsprüfbestand * EK netto_konz.',
	EK_NETTO_BNK NUMBER(38,4) COMMENT 'EK netto (Rechnungs-Einkaufspreis) zuzüglich Bezugsnebenkosten in Landeswährung.',
	EK_NETTO_BNK_KONZ NUMBER(38,4) COMMENT 'EK netto (Rechnungs-Einkaufspreis) zuzüglich Bezugsnebenkosten in Konzernwährung.',
	BETRAG_EK_NETTO_BNK_LGBEST_ERP_FREI NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem EK netto BNK in Landeswährung: Freier Bestand * (EK netto + Bezugsnebenkosten).',
	BETRAG_EK_NETTO_BNK_LGBEST_ERP_FREI_KONZ NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem EK netto BNK in Konzernwährung: Freier Bestand * (EK netto + Bezugsnebenkosten).',
	BETRAG_EK_NETTO_BNK_LGBEST_ERP_QUAL NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem EK netto BNK in Landeswährung: Qualitätsprüfbestand * (EK netto + Bezugsnebenkosten).',
	BETRAG_EK_NETTO_BNK_LGBEST_ERP_QUAL_KONZ NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem EK netto BNK in Konzernwährung: Qualitätsprüfbestand * (EK netto + Bezugsnebenkosten).',
	EK_NETTONETTO NUMBER(38,4) COMMENT 'EK netto (Rechnungs-Einkaufspreis) abzüglich Skonto in Landeswährung.',
	EK_NETTONETTO_KONZ NUMBER(38,4) COMMENT 'EK netto (Rechnungs-Einkaufspreis) abzüglich Skonto in Konzernwährung.',
	BETRAG_EK_NETTONETTO_LGBEST_ERP_FREI NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem EK netto netto in Landeswährung: Freier Bestand * (EK netto - Skonto).',
	BETRAG_EK_NETTONETTO_LGBEST_ERP_FREI_KONZ NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem EK netto netto in Konzernwährung: Freier Bestand * (EK netto - Skonto).',
	BETRAG_EK_NETTONETTO_LGBEST_ERP_QUAL NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem EK netto netto in Landeswährung: Qualitätsprüfbestand * (EK netto - Skonto).',
	BETRAG_EK_NETTONETTO_LGBEST_ERP_QUAL_KONZ NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem EK netto netto in Konzernwährung: Qualitätsprüfbestand * (EK netto - Skonto).',
	EK_MEP_OLK NUMBER(38,4) COMMENT 'Markteinstandspreis ohne Logistikkosten in Landeswährung (Ebene EKN3: EKN2 abzüglich dauerhaft regelmäßiger Konditionen und nachträglicher Vergütungen wie bspw. Finanz- oder Jahresbonus).',
	EK_MEP_OLK_KONZ NUMBER(38,4) COMMENT 'Markteinstandspreis ohne Logistikkosten in Konzernwährung  (Ebene EKN3: EKN2 abzüglich dauerhaft regelmäßiger Konditionen und nachträglicher Vergütungen wie bspw. Finanz- oder Jahresbonus).',
	BETRAG_EK_MEP_OLK_LGBEST_ERP_FREI NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem ek_mep_olk (Markteinstandspreis ohne Logistikkosten) in Landeswährung: Freier Bestand * ek_mep_olk.',
	BETRAG_EK_MEP_OLK_LGBEST_ERP_FREI_KONZ NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem ek_mep_olk (Markteinstandspreis ohne Logistikkosten) in Konzernwährung: Freier Bestand * ek_mep_olk_konz.',
	BETRAG_EK_MEP_OLK_LGBEST_ERP_QUAL NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem ek_mep_olk (Markteinstandspreis ohne Logistikkosten) in Landeswährung: Qualitätsprüfbestand * ek_mep_olk.',
	BETRAG_EK_MEP_OLK_LGBEST_ERP_QUAL_KONZ NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem ek_mep_olk (Markteinstandspreis ohne Logistikkosten) in Konzernwährung: Qualitätsprüfbestand * ek_mep_olk_konz.',
	EK_EINSTANDSPREIS NUMBER(38,4) COMMENT 'Einstandspreis in Landeswährung (Ebene EKN4: EKN3 abzüglich einmalig langfristiger Konditionen): Unterster EK, darf im VK nicht unterschritten werden.',
	EK_EINSTANDSPREIS_KONZ NUMBER(38,4) COMMENT 'Einstandspreis in Konzernwährung (Ebene EKN4: EKN3 abzüglich einmalig langfristiger Konditionen): Unterster EK, darf im VK nicht unterschritten werden.',
	BETRAG_EK_EINSTANDSPREIS_LGBEST_ERP_FREI NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem ek_einstandspreis in Landeswährung: Freier Bestand * ek_einstandspreis.',
	BETRAG_EK_EINSTANDSPREIS_LGBEST_ERP_FREI_KONZ NUMBER(38,4) COMMENT 'Bewerteter freier Bestand mit dem ek_einstandspreis in Konzernwährung: Freier Bestand * ek_einstandspreis_konz.',
	BETRAG_EK_EINSTANDSPREIS_LGBEST_ERP_QUAL NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem ek_einstandspreis in Landeswährung: Qualitätsprüfbestand * ek_einstandspreis.',
	BETRAG_EK_EINSTANDSPREIS_LGBEST_ERP_QUAL_KONZ NUMBER(38,4) COMMENT 'Bewerteter Qualitätsprüfbestand mit dem ek_einstandspreis in Konzernwährung: Qualitätsprüfbestand * ek_einstandspreis_konz.',
	EK_LOGISTIK NUMBER(38,4) COMMENT 'Konditionsmix für DE und KMO in Landeswährung, genutzt für bewertete Bestände im Bereich Logistik / SCM: Für DE wird der ek_netto_bnk (aus dbp_data.art_gp_wup_zu_per), für KMO der gld (gleitenderDurchschnitt aus dbp_data.art_bewertungskreis_periode) verwendet.',
	EK_LOGISTIK_KONZ NUMBER(38,4) COMMENT 'Konditionsmix für DE und KMO in Konzernwährung, genutzt für bewertete Bestände im Bereich Logistik / SCM: Für DE wird der ek_netto_bnk (aus dbp_data.art_gp_wup_zu_per), für KMO der gld (gleitenderDurchschnitt aus dbp_data.art_bewertungskreis_periode) verwendet.',
	BETRAG_EK_LOGISTIK_LGBEST_ERP_GESAMT NUMBER(38,4) COMMENT 'Bewerteter gesamter Bestand mit dem ek_logistik in Landeswährung: Gesamter Bestand * ek_logistik.',
	BETRAG_EK_LOGISTIK_LGBEST_ERP_GESAMT_KONZ NUMBER(38,4) COMMENT 'Bewerteter gesamter Bestand mit dem ek_logistik in Konzernwährung: Gesamter Bestand * ek_logistik_konz.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	UMRECHNUNGSKURS_HIST NUMBER(38,5) NOT NULL DEFAULT 0 COMMENT 'Historischer Berichtskurs aus dbp_data.kurs ',
	constraint PK_LAGERBESTAND_ERP_TAG_SUM primary key (MANDANT_ID, ART_ID, WUP_ID, NB_ID, LAGERORT_ID, DAT)
);